// @vitest-environment jsdom
import { effectScope } from 'vue'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { climbPoseOf, poseOf } from './pet-motion'
import { FOOT_PAD, PET_SIZE, PET_WIDTH } from './pet-physics'
import { usePetController, type PetHost } from './usePetController'

/** Parse the CSS transform generated by `poseOf` and apply it around `transform-origin: 50% 100%`. */
function transformPoint(css: string, lx: number, ly: number): { x: number; y: number } {
  const ox = PET_WIDTH / 2
  const oy = PET_SIZE
  let dx = lx - ox
  let dy = ly - oy

  const translateMatch = css.match(/translate\(([-\d.]+)px,\s*([-\d.]+)px\)/)
  const scaleXMatch = css.match(/scaleX\(([-\d.]+)\)/)
  const rotateMatch = css.match(/rotate\(([-\d.]+)deg\)/)
  const scaleYMatch = css.match(/scaleY\(([-\d.]+)\)/)

  const tx = translateMatch ? Number(translateMatch[1]) : 0
  const ty = translateMatch ? Number(translateMatch[2]) : 0
  const sx = scaleXMatch ? Number(scaleXMatch[1]) : 1
  const rad = ((rotateMatch ? Number(rotateMatch[1]) : 0) * Math.PI) / 180
  const sy = scaleYMatch ? Number(scaleYMatch[1]) : 1

  // CSS transforms apply right-to-left: scaleY -> rotate -> scaleX -> translate.
  dy *= sy
  const c = Math.cos(rad)
  const s = Math.sin(rad)
  const rx = dx * c - dy * s
  const ry = dx * s + dy * c
  dx = rx * sx
  dy = ry
  return { x: ox + dx + tx, y: oy + dy + ty }
}

const SVG_SCALE_X = PET_WIDTH / 36
const SVG_SCALE_Y = PET_SIZE / 20
// Landmarks from TxMiko RunningState.vue (viewBox="0 0 36 20").
const HEAD = { x: 4 * SVG_SCALE_X, y: 10 * SVG_SCALE_Y }
const TAIL = { x: 29 * SVG_SCALE_X, y: 9 * SVG_SCALE_Y }
const PAWS = { x: 12 * SVG_SCALE_X, y: 17 * SVG_SCALE_Y }
const EARS = { x: 8 * SVG_SCALE_X, y: 6 * SVG_SCALE_Y }

function makeRect(left: number, top: number, width: number, height: number): DOMRect {
  return {
    left,
    top,
    width,
    height,
    right: left + width,
    bottom: top + height,
    x: left,
    y: top,
    toJSON: () => ({})
  } as DOMRect
}

describe('pet-motion facing and wall-climb geometry', () => {
  it('orients TxMiko left when facing -1 and mirrors right when facing +1', () => {
    const leftCss = poseOf({ facing: -1 })
    const rightCss = poseOf({ facing: 1 })

    expect(leftCss).toBe('scaleX(1.000) rotate(0.0deg) scaleY(1.000)')
    expect(rightCss).toBe('scaleX(-1.000) rotate(0.0deg) scaleY(1.000)')

    const leftHead = transformPoint(leftCss, HEAD.x, HEAD.y)
    const leftTail = transformPoint(leftCss, TAIL.x, TAIL.y)
    expect(leftHead.x).toBeLessThan(leftTail.x)

    const rightHead = transformPoint(rightCss, HEAD.x, HEAD.y)
    const rightTail = transformPoint(rightCss, TAIL.x, TAIL.y)
    expect(rightHead.x).toBeGreaterThan(rightTail.x)
  })

  it('places head up, tail down, paws flush on the right wall, and ears facing inward', () => {
    const boundsRight = 900
    const buttonX = boundsRight - PET_WIDTH
    const css = poseOf(climbPoseOf(1))

    const head = transformPoint(css, HEAD.x, HEAD.y)
    const tail = transformPoint(css, TAIL.x, TAIL.y)
    const paws = transformPoint(css, PAWS.x, PAWS.y)
    const ears = transformPoint(css, EARS.x, EARS.y)

    expect(head.y).toBeLessThan(tail.y)
    expect(buttonX + paws.x).toBeCloseTo(boundsRight, 1)
    expect(buttonX + ears.x).toBeLessThan(buttonX + paws.x)
  })

  it('places head up, tail down, paws flush on the left wall, and ears facing inward', () => {
    const boundsLeft = 0
    const buttonX = boundsLeft
    const css = poseOf(climbPoseOf(-1))

    const head = transformPoint(css, HEAD.x, HEAD.y)
    const tail = transformPoint(css, TAIL.x, TAIL.y)
    const paws = transformPoint(css, PAWS.x, PAWS.y)
    const ears = transformPoint(css, EARS.x, EARS.y)

    expect(head.y).toBeLessThan(tail.y)
    expect(buttonX + paws.x).toBeCloseTo(boundsLeft, 1)
    expect(buttonX + ears.x).toBeGreaterThan(buttonX + paws.x)
  })
})

describe('usePetController wall climbing', () => {
  afterEach(() => {
    vi.useRealTimers()
    vi.restoreAllMocks()
  })

  function mountController() {
    vi.useFakeTimers()
    let now = 1000
    let rafQueue: Array<(ts: number) => void> = []
    vi.spyOn(document, 'hasFocus').mockReturnValue(true)
    vi.spyOn(performance, 'now').mockImplementation(() => now)
    vi.spyOn(window, 'requestAnimationFrame').mockImplementation((cb) => {
      rafQueue.push(cb)
      return rafQueue.length
    })
    vi.spyOn(window, 'cancelAnimationFrame').mockImplementation(() => {})

    const stage = document.createElement('div')
    const body = document.createElement('div')
    const box = document.createElement('div')
    const petNode = document.createElement('button')
    const shadowNode = document.createElement('div')
    stage.getBoundingClientRect = () => makeRect(0, 0, 900, 600)
    body.getBoundingClientRect = () => makeRect(0, 0, 900, 600)
    box.getBoundingClientRect = () => makeRect(200, 260, 500, 120)

    const host: PetHost = {
      stage: () => stage,
      body: () => body,
      box: () => box,
      input: () => null,
      empty: () => true,
      head: () => null
    }

    const scope = effectScope()
    const pet = scope.run(() =>
      usePetController(
        host,
        (k) => k,
        () => false
      )
    )!
    pet.bindPet(petNode)
    pet.bindShadow(shadowNode)
    pet.mount()

    function stepFrame(ms = 20): void {
      now += ms
      vi.advanceTimersByTime(ms)
      const pending = rafQueue
      rafQueue = []
      pending.forEach((cb) => cb(now))
    }

    function dragTo(clientX: number, clientY: number): void {
      pet.onPointerDown({ button: 0, clientX: 450, clientY: 220 } as PointerEvent)
      // Pointer lerp is 0.35 per move, so feed several moves to settle near the target wall.
      for (let i = 0; i < 20; i += 1) {
        now += 16
        window.dispatchEvent(
          Object.assign(new Event('pointermove'), { clientX, clientY }) as PointerEvent
        )
      }
      window.dispatchEvent(new Event('pointerup'))
      // Wake any idle setTimeout(IDLE_FRAME_MS) that was pending before drag started.
      vi.advanceTimersByTime(100)
    }

    return {
      pet,
      petNode,
      shadowNode,
      stepFrame,
      dragTo,
      cleanup: () => scope.stop()
    }
  }

  it('climbs right wall facing up with paws on the wall and hides the floating shadow', () => {
    const ctx = mountController()
    try {
      ctx.stepFrame()
      ctx.dragTo(885, 320)
      ctx.stepFrame()

      expect(ctx.pet.pose.value).toBe('climb')
      expect(ctx.petNode.style.getPropertyValue('--pet-pose')).toBe(poseOf(climbPoseOf(1)))
      expect(ctx.shadowNode.style.opacity).toBe('0')

      const beforeY = Number(ctx.petNode.style.transform.match(/,\s*([-\d.]+)px/)?.[1])
      ctx.stepFrame(100)
      const afterY = Number(ctx.petNode.style.transform.match(/,\s*([-\d.]+)px/)?.[1])
      expect(afterY).toBeLessThan(beforeY)
    } finally {
      ctx.cleanup()
    }
  })

  it('climbs left wall facing up with paws on the wall regardless of prior facing', () => {
    const ctx = mountController()
    try {
      ctx.stepFrame()
      // First snap to right wall so prior facing is +1, then drag to left wall.
      ctx.dragTo(885, 320)
      ctx.stepFrame()
      expect(ctx.petNode.style.getPropertyValue('--pet-pose')).toBe(poseOf(climbPoseOf(1)))

      ctx.dragTo(15, 320)
      ctx.stepFrame()

      expect(ctx.pet.pose.value).toBe('climb')
      expect(ctx.petNode.style.getPropertyValue('--pet-pose')).toBe(poseOf(climbPoseOf(-1)))
      expect(ctx.petNode.style.transform).toContain('translate3d(0.0px,')
    } finally {
      ctx.cleanup()
    }
  })

  it('transitions from climb to fall when reaching the top edge of the stage', () => {
    const ctx = mountController()
    try {
      ctx.stepFrame()
      ctx.dragTo(885, 90)
      ctx.stepFrame()
      expect(ctx.pet.pose.value).toBe('climb')

      for (let i = 0; i < 15; i += 1) {
        ctx.stepFrame(100)
        if (ctx.pet.pose.value !== 'climb') break
      }

      expect(ctx.pet.pose.value).toBe('fall')
      expect(FOOT_PAD).toBeGreaterThan(0)
    } finally {
      ctx.cleanup()
    }
  })

  it('walks toward the wall facing right, climbs right wall paws-on-wall, then walks left onto composer', () => {
    const ctx = mountController()
    try {
      ctx.stepFrame()
      // Drop in the right floor lane (outside composer x1=700+50.5 and outside WALL_SNAP=24).
      ctx.dragTo(790, 560)
      let sawMoveRight = false
      let sawClimbRight = false
      let sawLedgeLeft = false
      let prevX: number | null = null

      for (let i = 0; i < 300; i += 1) {
        ctx.stepFrame(40)
        const poseCss = ctx.petNode.style.getPropertyValue('--pet-pose')
        const curX = Number(ctx.petNode.style.transform.match(/translate3d\(([-\d.]+)px,/)?.[1])
        if (
          !sawClimbRight &&
          prevX !== null &&
          curX > prevX + 1 &&
          poseCss.startsWith('scaleX(-1.000)')
        ) {
          sawMoveRight = true
        }
        prevX = curX
        if (ctx.pet.pose.value === 'climb') {
          expect(poseCss).toBe(poseOf(climbPoseOf(1)))
          sawClimbRight = true
        }
        if (sawClimbRight && ctx.pet.pose.value === 'walk') {
          expect(poseCss).toBe(poseOf({ facing: -1 }))
          sawLedgeLeft = true
          break
        }
      }

      expect(sawMoveRight).toBe(true)
      expect(sawClimbRight).toBe(true)
      expect(sawLedgeLeft).toBe(true)
    } finally {
      ctx.cleanup()
    }
  })
})
